import React from 'react';

const PatientDashboard = () => {
  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <h1 className="text-3xl font-bold text-gray-900 mb-8">Patient Dashboard</h1>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <div className="health-card">
            <h3 className="text-lg font-semibold mb-2">Upcoming Appointments</h3>
            <p className="text-gray-600">View and manage your scheduled appointments</p>
          </div>
          <div className="health-card">
            <h3 className="text-lg font-semibold mb-2">Health Records</h3>
            <p className="text-gray-600">Access your medical history and reports</p>
          </div>
          <div className="health-card">
            <h3 className="text-lg font-semibold mb-2">Symptom Checker</h3>
            <p className="text-gray-600">Get AI-powered health assessments</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PatientDashboard;
